counters ATTRIBUTE GROUP
DESCRIPTION  The group of all counters;
REGISTERED AS  {ISO10589-ISIS.agoi counters (1)};

resettingTimer-B BEHAVIOUR DEFINED AS This attribute specifies the interval be tween certain events in the operation of the protocol state machine. If the value of this attribute is changed to a new value t while the protocol state machine is in operation, the implementation shall take the necessary steps to ensure that for any time interval which was in progress when the correspond ing attribute was changed, the next expiration of the that interval takes place t seconds from the original start of that interval, or immediately, whichever is later. The precision with which this time shall be im plemented shall be the same as that associated with the basic operation of the timer attribute;
replaceOnlyWhileDisabled-B BEHAVIOUR DEFINED AS This attribute shall only permit the RE PLACE operation to be performed on it while the MO is in the Disabled Operational State. An at tempt to perform a REPLACE operation while the MO is in the Enabled Operation State shall fail with the generation of the constraintViolation specific er ror.;
resourceLimiting-B BEHAVIOUR DEFINED AS This attribute places limits on some re source". In general implementations may allocate reources up to this limit when the managed object is enabled and it may be impossible to change the allo cation without first disabling and re-enabling the managed object. Therefore this International Stan dard only requires that it shall be possible to perform a REPLACE operation on this attribute while the MO is disabled. However some implementations may be able to to change the allocation of resources without first disabling the MO. In this case it is per mitted to increase the value of the atribute at any time, but it shall not be decreased below the cur rently used" value of the resource. Where an at tempt to perform a REPLACE operation fails either because the MO is enabled, or because an attempt has been made to decrease the value, the REPLACE operation shall fail with the generation of the con straintViolation specific error.;

FROM CommonMgmt IMPORT NSAPAddress, 
AddressPrefix, BinaryAbsoluteTime; 
PDU Type

lspID = ARRAY [0..7] OF Octet; 
systemID = ARRAY [0..5] OF Octet;
octetTimeStamp = BinaryAbsoluteTime;

RECORD  
adr: lspID;  (* 8 octet ID of LSP originator *)  
type: (AttachedLevel2IntermediateSystem,
UnattachedLevel2IntermediateSystem);  
seqnum: [0..SequenceModulus  1];  
LSPage: [0..MaxAge];  (*Remaining Lifetime *)  
expirationTime: TimeStamp;	
(*Time at which LSP age 
became zero (see 7.3.16.4). *)
SRMflags: ARRAY[1..(maximumCircuits)] OF 
BOOLEAN;
(*Indicates this LSP to be sent on this circuit. *)
SSNflags: ARRAY[1..maximumCircuits] OF 
BOOLEAN; 
(*Indicates that information about this LSP must be 
included in the next partial sequence number PDU 
transmitted on this circuit. *)
POINTER TO LSP; (*The received LSP *)
END;

RECORD
adr: systemId; (*6 octet ID of destination system *)
cost: [1..MaxPathMetric];
(*Cost of best path to destination system *)
adjacencies: ARRAY[1..maximumPathSplits] 
OF POINTER TO Adjacency;

(*Pointer to adjacency for forwarding to system adr 
*)
END;

RECORD 
adr: AddressPrefix;	(*destination prefix *)
cost: [1..MaxPathMetric];	
(*Cost of best path to destination prefix *)
adjacencies: ARRAY[1..maximumPathSplits] 
OF  POINTER TO Adjacency;
(*Pointer to adjacency for forwarding to prefix adr 
*)
END;

RECORD  
adr:systemId;
(*6 octet ID of destination system. Destination 
0 is special, meaningnearest level 2 
Intermediate system *)
splits: [0..maximumPathSplits];
(* Number of valid output adj's for reachingadr 
(0 indicates it is unreachable) *)
 nextHop: ARRAY[1..maximumPathSplits] OF 
POINTER TO adjacency; 
(*Pointer to adjacency for forwarding to destination 
system *)
END;

PROCEDURE Forward( level: (level1, level2), dest: NetworkLayerAddress, VAR adj: POINTER TO adjacency) : BOOLEAN
VAR adjArray: ARRAY OF ForwardingDatabaseRecords; temp, index, minQueue: CARDINAL;
BEGIN (*Set adjArray to appropriate database} *) IF level = level1 THEN adjArray := level1ForwardingDatabase ELSE adjArray := level2ForwardingDatabase END; (*Perform appropriate hashing function to obtain an index into the database *) IF Hash(level, dest, index) THEN IF adjArray[index].splits > 0 THEN (*Find minimum queue size for all equal cost paths *) minQueue := MaxUnsigned; temp := adjArray[index].lastChosen + 1; (*start off after last time *) FOR i := 1 TO adjArray[index].splits DO (*for all equal cost paths to dest *) IF temp > adjArray[index].splits THEN (*after end of valid entries, wrap to first *) temp := 1 ELSE temp := temp + 1 END; IF QueueSize(adjArray[index].nextHop[temp]) < minQueue THEN minQueue := QueueSize(adjArray[index].nextHop[tem p]); adj := adjArray[index].nextHop[temp]; adjArray[index].lastChosen := temp; END; Forward := true END;
ELSE Forward := false (*There must be at least one valid output adjacency *) END ELSE Forward := false (*Hash returned destination unknown *) END END forward;
